    return float(np.mean(vals))

# Dates treated as nationally non-standard for the December calibration level.
def is_calibration_day(d: date, start_md: tuple[int,int], end_md: tuple[int,int]) -> bool:
    return d.weekday()<5 and d not in {date(d.year,12,24),date(d.year,12,25),date(d.year,12,26),date(d.year,12,31)}

def ref_level(forecast_year: int, window: str) -> float:
    y=forecast_year-1
    if window=='dec01_20': start,end=date(y,12,1),date(y,12,20)
    elif window=='dec08_20': start,end=date(y,12,8),date(y,12,20)
    elif window=='dec15_20': start,end=date(y,12,15),date(y,12,20)
    elif window=='nov15_dec20': start,end=date(y,11,15),date(y,12,20)
    elif window=='dec01_23': start,end=date(y,12,1),date(y,12,23)
    else: raise ValueError(window)
    vals=[]; d=start
    while d<=end:
        if is_calibration_day(d,(start.month,start.day),(end.month,end.day)):
            vals.append(daily_mean(d))
        d+=timedelta(days=1)
    return float(np.mean(vals))

def nearest_analog_date(target: date, analog_year: int) -> date:
    if target.month==1 and target.day==1:
        return date(analog_year,1,1)
    candidates=[]
    for day in range(2,15):
        d=date(analog_year,1,day)
        if d.weekday()!=target.weekday(): continue
        if day==6 and target.day!=6: continue
        candidates.append(d)
    return min(candidates,key=lambda d:abs(d.day-target.day))

def epiphany_effect(through_year: int, hour: int | None=None) -> float:
    effects=[]
    for y in range(2015,through_year+1):
        eph=date(y,1,6)
        # Compare against nearest non-special same-weekday days on either side.
        comps=[]
        for delta in (-14,-7,7,14):
            d=eph+timedelta(days=delta)
            if d.year==y and d.month==1 and d.day not in (1,6):
                if hour is None: comps.append(daily_mean(d))
                else: comps.append(series[datetime(d.year,d.month,d.day,hour,tzinfo=next(iter(series)).tzinfo)])
        if comps:
            actual=daily_mean(eph) if hour is None else series[datetime(y,1,6,hour,tzinfo=next(iter(series)).tzinfo)]
            effects.append(actual/float(np.mean(comps)))
    return float(np.median(effects)) if effects else 1.0

def forecast(year: int, window: str | None, years: int, decay: float, eph: str) -> np.ndarray:
