            ad=nearest_analog_date(td,ay)
            scale=target_ref/ref_level(ay+1,window) if window else 1.0
            w=decay**(age-1)
            vals=np.array([series[datetime(ad.year,ad.month,ad.day,h,tzinfo=next(iter(series)).tzinfo)] for h in range(24)])*scale
            analogs.append((w,vals))
