    for r in csv.DictReader(f): series[datetime.fromisoformat(r['utc_timestamp'])]=float(r['DE_load_actual_entsoe_transparency'])
tz=next(iter(series)).tzinfo

def prof(d): return np.array([series[datetime(d.year,d.month,d.day,h,tzinfo=tz)] for h in range(24)])
def dates(a,b):
    while a<=b: yield a; a+=timedelta(days=1)
def base(year, dow, window, mode):
    y=year-1
    rg={'dec01_20':(date(y,12,1),date(y,12,20)),'dec08_20':(date(y,12,8),date(y,12,20)),'dec15_20':(date(y,12,15),date(y,12,20)),'nov15_dec20':(date(y,11,15),date(y,12,20))}[window]
    ds=[d for d in dates(*rg) if d.weekday()==dow]
    p=np.mean([prof(d) for d in ds],axis=0)
    return p if mode=='hourly' else np.full(24,float(np.mean(p)))
def analog(td, ay, special6):
    if td.day==1: return date(ay,1,1)
    if td.day==6 and special6: return date(ay,1,6)
    cs=[date(ay,1,d) for d in range(2,15) if date(ay,1,d).weekday()==td.weekday() and d!=6]
    return min(cs,key=lambda x:abs(x.day-td.day))
