        ay=year-age
        if ay<2015: continue
        ad=analog(td,ay,special6)
        ap=prof(ad); ab=base(ay+1,ad.weekday(),window,base_mode)
        if ratio_mode=='hourly': ratio=ap/ab
        elif ratio_mode=='scalar': ratio=np.full(24,float(np.mean(ap)/np.mean(ab)))
        elif ratio_mode=='shape_scalar':
            # Preserve analog intraday shape, but calibrate its daily level relative to its December baseline.
            ratio=(ap/np.mean(ap))*float(np.mean(ap)/np.mean(ab))
        w=decay**(age-1); ratios.append((w,ratio))
