 for r in csv.DictReader(f): hourly[datetime.fromisoformat(r['utc_timestamp'])]=float(r['DE_load_actual_entsoe_transparency'])
tz=next(iter(hourly)).tzinfo
def hp(d): return np.array([hourly[datetime(d.year,d.month,d.day,h,tzinfo=tz)] for h in range(24)])
start=min(hourly).date(); end=max(hourly).date()
daily={}; d=start
while d<=end:
 daily[d]=float(np.mean(hp(d))); d+=timedelta(days=1)

def doy_frac(d):
 return (d-date(d.year,1,1)).days / (366 if date(d.year,12,31).timetuple().tm_yday==366 else 365)

def feature(d,lagset,special,roll):
 x=[1.0]
 for lag in lagset: x.append(daily.get(d-timedelta(days=lag),np.nan))
 if roll:
  for n in (7,14,28):
   vals=[daily.get(d-timedelta(days=i),np.nan) for i in range(1,n+1)]
   x.append(float(np.mean(vals)) if all(np.isfinite(vals)) else np.nan)
 # day of week
 x += [1.0 if d.weekday()==k else 0.0 for k in range(7)]
 # smooth annual terms
 z=doy_frac(d)
 for k in range(1,9): x += [math.sin(2*math.pi*k*z),math.cos(2*math.pi*k*z)]
 # structural trend, centered
 tr=(d-date(2015,1,1)).days/365.25
 x += [tr,tr*tr]
 if special:
