 ds=[]; d=max(start+timedelta(days=max(lagset+[28])),date(year-window_years,1,1) if window_years else start)
 while d<cutoff:
  x=feature(d,lagset,special,roll)
  if np.all(np.isfinite(x)): ds.append((x,daily[d]))
  d+=timedelta(days=1)
 X=np.stack([x for x,_ in ds]); y=np.array([v for _,v in ds])
 # standardize non-intercept columns
 mu=X[:,1:].mean(axis=0); sd=X[:,1:].std(axis=0); sd[sd<1e-9]=1
 Z=np.column_stack([np.ones(len(X)),(X[:,1:]-mu)/sd])
 reg=np.eye(Z.shape[1]); reg[0,0]=0
 beta=np.linalg.solve(Z.T@Z+lam*reg,Z.T@y)
