from __future__ import annotations

import csv
import math
from datetime import date, datetime, timedelta
from pathlib import Path

import numpy as np

root = Path('/Users/doob/dev/energy_forecast_ws/94eee4/project/runs/94eee4')
source_path = root / 'opsd_de_load.csv'
output_path = root / 'forecast_jan_2020.csv'
forecast_year = 2020
forecast_start = datetime.fromisoformat('2020-01-01 00:00:00+00:00')

hourly: dict[datetime, float] = {}
with source_path.open(newline='') as source:
    for row in csv.DictReader(source):
        timestamp = datetime.fromisoformat(row['utc_timestamp'])
        if timestamp < forecast_start:
            hourly[timestamp] = float(row['DE_load_actual_entsoe_transparency'])

timezone = forecast_start.tzinfo


def profile(day: date) -> np.ndarray:
    return np.array([
        hourly[datetime(day.year, day.month, day.day, hour, tzinfo=timezone)]
        for hour in range(24)
    ])


def daily_mean(day: date) -> float:
    return float(np.mean(profile(day)))


def december_level(year: int) -> float:
    previous_year = year - 1
    values = [
        daily_mean(date(previous_year, 12, day_number))
        for day_number in range(15, 21)
        if date(previous_year, 12, day_number).weekday() < 5
    ]
    return float(np.mean(values))


def normal_january_day(year: int, weekday: int) -> date:
    return next(
        date(year, 1, day_number)
        for day_number in range(8, 15)
        if date(year, 1, day_number).weekday() == weekday
    )


def working_day_rank(day: date) -> int | None:
    if day.month != 1 or day.day <= 1 or day.weekday() >= 5:
        return None
    return sum(
        date(day.year, 1, day_number).weekday() < 5
        for day_number in range(2, day.day + 1)
    )


def date_for_working_day_rank(year: int, rank: int) -> date:
    current_rank = 0
    for day_number in range(2, 15):
        candidate = date(year, 1, day_number)
        if candidate.weekday() < 5:
            current_rank += 1
            if current_rank == rank:
                return candidate
    raise ValueError(f'No working day rank {rank} in January {year}')


def working_day_effect(year: int, rank: int) -> float:
    ratios: list[float] = []
    for historical_year in range(2015, year):
        day = date_for_working_day_rank(historical_year, rank)
        if day.day != 6:
            ratios.append(daily_mean(day) / daily_mean(day + timedelta(days=7)))
    return float(np.median(ratios))


def epiphany_effect(year: int) -> float:
    ratios: list[float] = []
    for historical_year in range(2015, year):
        day = date(historical_year, 1, 6)
        if day.weekday() < 5:
            ratios.append(daily_mean(day) / daily_mean(day + timedelta(days=7)))
    return float(np.median(ratios))


def calendar_analog_forecast(year: int) -> np.ndarray:
    forecast: list[float] = []
    target_level = december_level(year)
    for day_number in range(1, 8):
        target = date(year, 1, day_number)
        analog_profiles: list[np.ndarray] = []
        for historical_year in range(2015, year):
            analog = (
                date(historical_year, 1, 1)
                if day_number == 1
                else normal_january_day(historical_year, target.weekday())
            )
            level_scale = target_level / december_level(historical_year + 1)
            analog_profiles.append(profile(analog) * level_scale)
        day_forecast = np.mean(analog_profiles, axis=0)
        rank = working_day_rank(target)
        if rank is not None and rank <= 3 and target.day != 6:
            day_forecast *= working_day_effect(year, rank)
        if target.day == 6 and target.weekday() < 5:
            day_forecast *= epiphany_effect(year)
        forecast.extend(day_forecast.tolist())
    return np.array(forecast)


daily: dict[date, float] = {}
day = min(hourly).date()
while day <= max(hourly).date():
    daily[day] = daily_mean(day)
    day += timedelta(days=1)


def nearest_hourly_analog(target: date, analog_year: int) -> date:
    if target.day == 1:
        return date(analog_year, 1, 1)
    candidates = [
        date(analog_year, 1, day_number)
        for day_number in range(2, 15)
        if date(analog_year, 1, day_number).weekday() == target.weekday()
        and day_number != 6
    ]
    return min(candidates, key=lambda candidate: abs(candidate.day - target.day))


def ridge_features(target: date) -> np.ndarray:
    values: list[float] = [1.0, daily[target - timedelta(days=364)]]
    values.extend(float(target.weekday() == weekday) for weekday in range(7))
    days_in_year = 366 if date(target.year, 12, 31).timetuple().tm_yday == 366 else 365
    year_fraction = (target - date(target.year, 1, 1)).days / days_in_year
    for harmonic in range(1, 9):
        angle = 2 * math.pi * harmonic * year_fraction
        values.extend((math.sin(angle), math.cos(angle)))
    trend = (target - date(2015, 1, 1)).days / 365.25
    values.extend((trend, trend * trend))
    special_dates = [(12, day_number) for day_number in range(20, 32)] + [
        (1, day_number) for day_number in range(1, 15)
    ]
    values.extend(float((target.month, target.day) == special) for special in special_dates)
    return np.array(values)


def ridge_daily_forecast(year: int) -> np.ndarray:
    rows: list[tuple[np.ndarray, float]] = []
    day = date(2016, 1, 1)
    training_end = date(year, 1, 1)
    while day < training_end:
        features = ridge_features(day)
        if np.all(np.isfinite(features)):
            rows.append((features, daily[day]))
        day += timedelta(days=1)

    design = np.stack([features for features, _ in rows])
    targets = np.array([target for _, target in rows])
    means = design[:, 1:].mean(axis=0)
    scales = design[:, 1:].std(axis=0)
    scales[scales < 1e-9] = 1.0
    standardized = np.column_stack([
        np.ones(len(design)),
        (design[:, 1:] - means) / scales,
    ])
    penalty = np.eye(standardized.shape[1])
    penalty[0, 0] = 0.0
    coefficients = np.linalg.solve(
        standardized.T @ standardized + 0.1 * penalty,
        standardized.T @ targets,
    )

    predictions: list[float] = []
    for day_number in range(1, 8):
        features = ridge_features(date(year, 1, day_number))
        standardized_features = np.concatenate((
            np.array([1.0]),
            (features[1:] - means) / scales,
        ))
        predictions.append(float(standardized_features @ coefficients))
    return np.array(predictions)


def ridge_hourly_forecast(year: int) -> np.ndarray:
    forecast: list[float] = []
    weights = (1.0, 0.5, 0.25, 0.125)
    for day_number, predicted_mean in enumerate(ridge_daily_forecast(year), start=1):
        target = date(year, 1, day_number)
        weighted_shapes: list[tuple[float, np.ndarray]] = []
        for age, weight in enumerate(weights, start=1):
            analog = nearest_hourly_analog(target, year - age)
            analog_profile = profile(analog)
            weighted_shapes.append((weight, analog_profile / np.mean(analog_profile)))
        shape = sum(weight * values for weight, values in weighted_shapes) / sum(weights)
        forecast.extend((predicted_mean * shape).tolist())
    return np.array(forecast)


forecast = 0.6 * calendar_analog_forecast(forecast_year) + 0.4 * ridge_hourly_forecast(forecast_year)
with output_path.open('w', newline='') as output:
    writer = csv.writer(output)
    writer.writerow(['utc_timestamp', 'DE_load_forecast'])
    for offset, value in enumerate(forecast):
        timestamp = forecast_start + timedelta(hours=offset)
        writer.writerow([timestamp.isoformat(sep=' '), f'{value:.1f}'])

print(output_path)
print('forecast_rows', len(forecast))
print('forecast_min_mw', f'{forecast.min():.1f}')
print('forecast_max_mw', f'{forecast.max():.1f}')
print('forecast_mean_mw', f'{forecast.mean():.1f}')
for day_index in range(7):
    values = forecast[day_index * 24:(day_index + 1) * 24]
    print(
        (forecast_start + timedelta(days=day_index)).date(),
        f'mean={values.mean():.1f}',
        f'min={values.min():.1f}',
        f'max={values.max():.1f}',
    )
